document.addEventListener('keydown',e=>{if(mode==='dialogue'||mode==='journal'){if(e.code==='Escape'&&!e.repeat){e.preventDefault();closeDialogue()}return}if(mode==='settings'){if(e.code==='Escape'&&!e.repeat){e.preventDefault();closeSettings()}return}if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyJ','KeyK','KeyL'].includes(e.code))e.preventDefault();if(!keys[e.code])pressed[e.code]=true;keys[e.code]=true;if(e.code==='Escape'&&!e.repeat)pause()});document.addEventListener('keyup',e=>{keys[e.code]=false});window.addEventListener('blur',()=>{focused=false;for(const k in keys)delete keys[k];for(const k in pressed)delete pressed[k];for(const k in padKeys)delete padKeys[k];padAxis=0;if(mode==='play'||mode==='intro')pause()});window.addEventListener('focus',()=>{focused=true});document.getElementById('start').onclick=()=>{if(audioPreferencesChosen)initAudio();else enableAudio();reset()};document.getElementById('pause').onclick=pause;document.getElementById('title-settings').onclick=openSettings;document.getElementById('settings-back').onclick=closeSettings;document.getElementById('skip').onclick=finishIntro;document.getElementById('fullscreen').onclick=toggleFullscreen;document.addEventListener('fullscreenchange',()=>{document.getElementById('fullscreen').textContent=document.fullscreenElement?'SAIR DA TELA CHEIA':'ENTRAR EM TELA CHEIA'});document.getElementById('effects-volume').addEventListener('input',e=>{effectsVolume=Number(e.target.value)/100;if(effectsBus)effectsBus.gain.setTargetAtTime(effectsVolume,audio.currentTime,.05)});document.getElementById('sound').onclick=()=>{if(!initAudio())return;audioPreferencesChosen=true;sound=!sound;syncAudioUI()};
document.getElementById('music').onclick=()=>{if(!initAudio())return;audioPreferencesChosen=true;music=!music;musicTheme='';syncAudioUI()};
document.getElementById('volume').addEventListener('input',e=>{musicVolume=Number(e.target.value)/100});
document.addEventListener('pointerdown',()=>{if(audio&&audio.state==='suspended')audio.resume().catch(()=>{})});

document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true;pressed[b.dataset.key]=true});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>{keys[b.dataset.key]=false})});
reset();mode='title';overlay.hidden=false;toastTime=0;installContinue();requestAnimationFrame(loop);

===BUILD===
const fs=require('fs'),path=require('path');
const root=path.join(__dirname,'..');
const manifest=JSON.parse(fs.readFileSync(path.join(root,'assets/manifest.json')));
const sprites=Object.entries(manifest.embedded).map(([id,[file,frames]])=>`loadArt(${JSON.stringify(id)},'data:image/png;base64,${fs.readFileSync(path.join(root,'assets/sprites',file)).toString('base64')}',${frames});`).join('\n');
const source=['core.js','adventure.js','input.js'].map(file=>fs.readFileSync(path.join(root,'src',file),'utf8')).join('\n').replace('/* EMBEDDED_SPRITES */',sprites);
new(require('vm').Script)(source);
const html=fs.readFileSync(path.join(root,'src/shell.html'),'utf8').replace('/* GAME_CODE */',()=>source);
fs.writeFileSync(path.join(root,'index.html'),html);
console.log('Standalone atualizado: index.html');

